Mkt3L10n.socialAppDashboard = {
  Share_Rate_percentage: ":<div style=\\\"font-weight: bold\\\">Share Rate:</div><p>The percentage of visits that generate a share.</p><br/><div style=\\\"font-weight: bold\\\">Clickback Rate:</div> <p>The number of resulting clicks per share.</p><br/><div style=\\\"font-weight: bold\\\">Social Lift:</div><p>The ratio of social visits (coming from a shared URL) to the number of non-social visits (coming from other sources), expressed in percent.</p><br/>:",
  Visits_number_sessions_Campaign: ":<div style=\\\"font-weight: bold\\\">Visits:</div><p>The number of times users have been to your site (unique sessions initiated by your visitors) during a given period. Users that leave and return within 30 minutes will be counted as part of the original session. Breaks in activity of more than 30 minutes or a browser close and restart will result in a new session or visit.</p><br/><div style=\\\"font-weight: bold\\\">Campaign Visits:</div><p>The number of visits to all campaigns on your site. Visits to a page with multiple placements of the same campaign count as one campaign visit. Visits to multiple pages with placements of the same campaign also count as one campaign visit.</p><br/><div style=\\\"font-weight: bold\\\">Interactions:</div><p>The number of times users have completed a social action, e.g. voting, rating, sharing, posting a comment, signing up for an offer, sharing a video, and so on. </p><br/><div style=\\\"font-weight: bold\\\">Shares:</div><p>The number of times users have shared a message to a social network.</p><br/><div style=\\\"font-weight: bold\\\">Resulting Clicks:</div><p>The number of page views generated by shared links from a campaign.</p><br/><div style=\\\"font-weight: bold\\\">Conversions:</div><p>The number of times users have completed a specific action (for example, purchasing a product), as defined by a conversion script implemented on your site. \\\"Registrations\\\" (or first time users who interact as a result of following a shared link back to your site) is the default conversion event if no conversion script is deployed.</p><br/>:",
  Social_Funnel: ":Social Funnel:",
  Social_Dashboard: ":Social Dashboard:",
  Total_Profiles_number_users_who_signed_social_network: ":<div style=\\\"font-weight: bold\\\">Total Profiles:</div><p>The number of users who have signed in to a social network (or interacted) with a social app.</p><br/> <div style=\\\"font-weight: bold\\\">Influencers:</div><p>The number of users who have generated at least one referred visit from a shared link.</p><br/><div style=\\\"font-weight: bold\\\">Social Reach:</div><p>The sum total of all users' connections in a campaign. For social network users, we count the number of their friends at the time they share; for email users, we count the number of recipients of the e-mail they initiate.</p><br/><div style=\\\"font-weight: bold\\\">Social Impressions:</div><p>The number of times the messages shared from a campaign might have been seen. This is calculated by multiplying each sharer's social reach by the number of times they have shared, and adding these values up for all sharers.</p><br/>:",
  Share_Metrics: ":Share Metrics:",
  Data_will_be_updated_within_24_hours: ":Data will be updated within 24 hours:",
  Date_of_Activity: ":Date of Activity:",
  Audience: ":Audience <span style='font-weight:normal'>(Total Profiles: {0})</span>:",
  Last_Updated: ":Last Updated:"
};
